const resolveKbDanglingLinks = `-- name: ResolveKbDanglingLinks :exec
UPDATE kb_link AS l SET to_page_id = u.page_id
FROM (
    SELECT
        unnest($2::text[]) AS path,
        unnest($3::uuid[]) AS page_id
) AS u
WHERE l.knowledge_base_id = $1
  AND l.to_page_id IS NULL
  AND l.to_path = u.path
`

type ResolveKbDanglingLinksParams struct {
	KnowledgeBaseID pgtype.UUID   `json:"knowledge_base_id"`
	Paths           []string      `json:"paths"`
	PageIds         []pgtype.UUID `json:"page_ids"`
}

// Points links written to a path that had no page yet at the page now there.
func (q *Queries) ResolveKbDanglingLinks(ctx context.Context, arg ResolveKbDanglingLinksParams) error {
	_, err := q.db.Exec(ctx, resolveKbDanglingLinks, arg.KnowledgeBaseID, arg.Paths, arg.PageIds)
	return err
}

