const upsertKbPages = `-- name: UpsertKbPages :exec
INSERT INTO kb_page (
    id, workspace_id, knowledge_base_id, parent_id, position, slug, type, title, description,
    frontmatter, blocks, search_text, head_revision_id, stale_after, deleted_at
)
SELECT
    u.id, $1::uuid, $2::uuid, u.parent_id,
    u.position, u.slug, u.type, u.title, u.description, u.frontmatter, u.blocks, u.search_text,
    u.head_revision_id, u.stale_after, CASE WHEN u.deleted THEN now() END
FROM (
    SELECT
        unnest($3::uuid[]) AS id,
        unnest($4::uuid[]) AS parent_id,
        unnest($5::text[]) AS position,
        unnest($6::text[]) AS slug,
        unnest($7::text[]) AS type,
        unnest($8::text[]) AS title,
        unnest($9::text[]) AS description,
        unnest($10::jsonb[]) AS frontmatter,
        unnest($11::jsonb[]) AS blocks,
        unnest($12::text[]) AS search_text,
        unnest($13::uuid[]) AS head_revision_id,
        unnest($14::timestamptz[]) AS stale_after,
        unnest($15::boolean[]) AS deleted
) AS u
ON CONFLICT (id) DO UPDATE SET
    parent_id = EXCLUDED.parent_id,
    position = EXCLUDED.position,
    slug = EXCLUDED.slug,
    type = EXCLUDED.type,
    title = EXCLUDED.title,
    description = EXCLUDED.description,
    frontmatter = EXCLUDED.frontmatter,
    blocks = EXCLUDED.blocks,
    search_text = EXCLUDED.search_text,
    head_revision_id = EXCLUDED.head_revision_id,
    stale_after = EXCLUDED.stale_after,
    deleted_at = CASE WHEN EXCLUDED.deleted_at IS NULL THEN NULL ELSE COALESCE(kb_page.deleted_at, EXCLUDED.deleted_at) END,
    updated_at = now()
`

type UpsertKbPagesParams struct {
	WorkspaceID     pgtype.UUID          `json:"workspace_id"`
	KnowledgeBaseID pgtype.UUID          `json:"knowledge_base_id"`
	Ids             []pgtype.UUID        `json:"ids"`
	ParentIds       []pgtype.UUID        `json:"parent_ids"`
	Positions       []string             `json:"positions"`
	Slugs           []string             `json:"slugs"`
	Types           []string             `json:"types"`
	Titles          []string             `json:"titles"`
	Descriptions    []string             `json:"descriptions"`
	Frontmatters    [][]byte             `json:"frontmatters"`
	Blocks          [][]byte             `json:"blocks"`
	SearchTexts     []string             `json:"search_texts"`
	HeadRevisionIds []pgtype.UUID        `json:"head_revision_ids"`
	StaleAfters     []pgtype.Timestamptz `json:"stale_afters"`
	Deleted         []bool               `json:"deleted"`
}

// Moves merged pages to their new head revisions, creating the pages the
// merge adds; the arrays are parallel.
func (q *Queries) UpsertKbPages(ctx context.Context, arg UpsertKbPagesParams) error {
	_, err := q.db.Exec(ctx, upsertKbPages,
		arg.WorkspaceID,
		arg.KnowledgeBaseID,
		arg.Ids,
		arg.ParentIds,
		arg.Positions,
		arg.Slugs,
		arg.Types,
		arg.Titles,
		arg.Descriptions,
		arg.Frontmatters,
		arg.Blocks,
		arg.SearchTexts,
		arg.HeadRevisionIds,
		arg.StaleAfters,
		arg.Deleted,
	)
	return err
}
